// Calculate planning window for the coming month
const now = new Date();
const year = now.getFullYear();
const month = now.getMonth(); // 0-indexed, so this is current month

// Start = 1st of next month (or today if testing)
const startDate = new Date(year, month + 1, 1);
const endDate = new Date(year, month + 2, 0); // Last day of next month

const formatDate = (d) => d.toISOString().split('T')[0];

// Build list of all dates in the month
const dates = [];
const cursor = new Date(startDate);
while (cursor <= endDate) {
  dates.push(formatDate(new Date(cursor)));
  cursor.setDate(cursor.getDate() + 1);
}

// Competitor TikTok handles to scrape
const competitors = [
  'rowancheung',
  'itsaria.ai',
  'learnaiwithkaylee',
  'aiwiththeus',
  'letscyber',
  'zeenatautomation'
];

return [{
  json: {
    startDate: formatDate(startDate),
    endDate: formatDate(endDate),
    monthLabel: startDate.toLocaleString('default', { month: 'long', year: 'numeric' }),
    totalDays: dates.length,
    totalPosts: dates.length * 2,
    dates,
    competitors,
    planningTimestamp: new Date().toISOString()
  }
}];

// Store the Apify run ID for polling
const runData = $input.first().json;
const planningData = $('Set Planning Window').first().json;

return [{
  json: {
    ...planningData,
    apifyRunId: runData.data?.id || runData.id || null,
    apifyStatus: runData.data?.status || 'RUNNING'
  }
}];

// Process competitor TikTok data — extract top performers
const rawResults = $input.all();
const planningData = $('Store Run ID').first().json;

// Flatten all posts from the response
let allPosts = [];
for (const item of rawResults) {
  if (Array.isArray(item.json)) {
    allPosts = allPosts.concat(item.json);
  } else if (item.json && typeof item.json === 'object') {
    allPosts.push(item.json);
  }
}

// Calculate save rate and engagement for each post
const scoredPosts = allPosts
  .filter(p => p.playCount > 1000) // Filter out low-view posts
  .map(p => {
    const plays = p.playCount || p.stats?.playCount || 0;
    const likes = p.diggCount || p.stats?.diggCount || 0;
    const saves = p.collectCount || p.stats?.collectCount || 0;
    const comments = p.commentCount || p.stats?.commentCount || 0;
    const shares = p.shareCount || p.stats?.shareCount || 0;
    const saveRate = plays > 0 ? ((saves / plays) * 100).toFixed(2) : 0;
    const engagementRate = plays > 0 ? (((likes + saves + comments + shares) / plays) * 100).toFixed(2) : 0;

    return {
      handle: p.authorMeta?.name || p.author?.uniqueId || 'unknown',
      desc: (p.desc || p.text || '').substring(0, 200),
      plays,
      likes,
      saves,
      saveRate: parseFloat(saveRate),
      engagementRate: parseFloat(engagementRate),
      duration: p.videoMeta?.duration || p.video?.duration || 0,
      hashtags: (p.hashtags || []).map(h => h.name || h).slice(0, 5).join(', ')
    };
  })
  .sort((a, b) => b.saveRate - a.saveRate);

// Top 20 posts by save rate
const top20 = scoredPosts.slice(0, 20);

// Identify patterns
const avgSaveRate = top20.length > 0
  ? (top20.reduce((s, p) => s + p.saveRate, 0) / top20.length).toFixed(2)
  : 0;

const viralPosts = scoredPosts.filter(p => p.saveRate >= 3);

// Summarize for Gemini
const topPostsSummary = top20.map((p, i) =>
  `${i + 1}. @${p.handle}: "${p.desc}" | ${p.plays.toLocaleString()} views | ${p.saveRate}% save rate | ${p.duration}s | Tags: ${p.hashtags}`
).join('\n');

return [{
  json: {
    ...planningData,
    topPostsSummary: topPostsSummary || 'No competitor data available — use general AI consulting trends',
    totalPostsAnalyzed: allPosts.length,
    viralPostCount: viralPosts.length,
    avgSaveRate,
    topHooks: top20.slice(0, 5).map(p => p.desc.substring(0, 100))
  }
}];

// Fetch top 10 HN stories for AI trend context
const ids = $input.first().json;
const top10 = Array.isArray(ids) ? ids.slice(0, 10) : [];

// Return the IDs to be fetched individually
return top10.map(id => ({ json: { storyId: id } }));

// Aggregate all trend signals into a summary for Gemini
const competitorData = $('Analyze Competitor Data').first().json;
const hnStories = $input.all();

// Filter for AI-relevant HN stories
const aiKeywords = ['ai', 'llm', 'gpt', 'claude', 'gemini', 'automation', 'machine learning', 'agent', 'openai', 'anthropic', 'ml', 'artificial intelligence', 'robotics', 'chatbot'];

const relevantStories = hnStories
  .filter(item => {
    const title = (item.json.title || '').toLowerCase();
    return aiKeywords.some(kw => title.includes(kw));
  })
  .map(item => item.json.title)
  .filter(Boolean)
  .slice(0, 10);

const trendingTopics = relevantStories.length > 0
  ? relevantStories.join('\n')
  : 'AI agents, workflow automation, prompt engineering, AI for small business, no-code AI tools, AI ROI measurement';

return [{
  json: {
    ...competitorData,
    trendingTopics
  }
}];

// Parse Gemini's JSON calendar response
const geminiOutput = $input.first().json;
const planningData = $('Aggregate Trend Data').first().json;

let responseText = '';
if (typeof geminiOutput === 'string') responseText = geminiOutput;
else if (geminiOutput.response) responseText = String(geminiOutput.response);
else if (geminiOutput.text) responseText = String(geminiOutput.text);
else if (geminiOutput.content) responseText = String(geminiOutput.content);
else if (geminiOutput.output) responseText = String(geminiOutput.output);
else responseText = JSON.stringify(geminiOutput);

let calendar;
try {
  // Strip markdown if present
  let jsonMatch = responseText.match(/```json\s*([\s\S]*?)\s*```/);
  if (!jsonMatch) jsonMatch = responseText.match(/```\s*([\s\S]*?)\s*```/);
  if (!jsonMatch) jsonMatch = responseText.match(/(\[[\s\S]*\])/);
  const jsonString = jsonMatch ? jsonMatch[1].trim() : responseText.trim();
  calendar = JSON.parse(jsonString);
  if (!Array.isArray(calendar)) throw new Error('Response is not an array');
} catch (e) {
  // Fallback: generate a minimal calendar structure
  calendar = planningData.dates.flatMap(date => [
    { date, slot: 'morning', pillar: 'Pillar 1 - AI News Breakdown', hook_number: 1, title: 'AI News for ' + date, content_brief: 'Cover the latest AI news relevant to business owners.', video_format: '60-90s Research/Demo', trending_angle: 'General AI trends' },
    { date, slot: 'evening', pillar: 'Pillar 6 - Live Workflow Demo', hook_number: 11, title: 'AI Workflow Demo ' + date, content_brief: 'Show a live AI workflow that automates a business task.', video_format: '60-90s Research/Demo', trending_angle: 'AI automation' }
  ]);
}

// Add metadata to each record
const enrichedCalendar = calendar.map((post, idx) => ({
  ...post,
  post_index: idx + 1,
  month_label: planningData.monthLabel,
  brand: 'Mankind AI',
  status: 'Generate Content',
  created_by: 'MKAI Monthly Planner'
}));

// Return as separate items for Airtable batch create
return enrichedCalendar.map(post => ({ json: post }));

// Build a summary of what was planned
const items = $input.all();
const planningData = $('Aggregate Trend Data').first().json;

const pillarCounts = {};
for (const item of items) {
  const pillar = item.json.fields?.Pillar || 'Unknown';
  pillarCounts[pillar] = (pillarCounts[pillar] || 0) + 1;
}

return [{
  json: {
    summary: `MKAI Monthly Planner Complete`,
    month: planningData.monthLabel,
    totalRecordsCreated: items.length,
    pillarBreakdown: pillarCounts,
    nextSteps: '1. Caption Generator will auto-generate captions. 2. Review captions in Airtable. 3. Set approved posts to Ready to Post. 4. Publisher runs at 9AM and 7PM ET daily.',
    airtableUrl: 'https://airtable.com/appCdEGI61nC515lh'
  }
}];
